class ConfPersonaRetencion extends BaseConfPersonaRetencion
{
    /**
     * Obtener los datos de retenciones dado el id persona y entidad.
     *
     * @param int $idpersona Identificador de la persona.
     * @param int $identidad Identificador de la entidad.
     *
     * @return array    Listado de los datos de retencion de una persona.
     */
    public function obtenerDatosPersonaRetencion($identidad, $texto, $inicio = 0, $limite = 5)
    {
        $arrayfinal = array();
        $cont = 0;
        //$objDatGestNomMod = new DatGestionarNominasModel();
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $conn->beginTransaction();
        $sqlconcat = (!empty($texto)) ? " and (doc.numero ilike '%$texto%' or dp.nombre ilike '%$texto%' or dp.snombre ilike '%$texto%' or dp.papel ilike '%$texto%' or dp.sapel ilike '%$texto%')" : "";
        $sqlDatosPersona = "select DISTINCT (dco.idpersona),cpr.idconfpersonaretencion,cpr.identidad, dp.nombre, 
            (CASE WHEN (dp.snombre is null) then '' else dp.snombre end ) as snombre, 
            dp.papel, dp.sapel, doc.numero as numid, dco.idcargo, nc.denominacion as denomcargo,
            (CASE WHEN dco.idplantillanominal is not null THEN dco.idplantillanominal WHEN cpn.idplantillanominal is not null THEN cpn.idplantillanominal ELSE -1 END) as idplantillanominal,
            (CASE WHEN dco.idplantillanominal is not null THEN (select cpx.denominacion from mod_nomina.conf_plantillanominal cpx where cpx.idplantillanominal = dco.idplantillanominal) WHEN cpn.denominacion <> '' THEN cpn.denominacion ELSE 'Sin plantilla nominal' END) as plantilla,
            cpn.orden as orden, nfe.nivel as ordencargo

            from mod_nomina.conf_personaretencion  cpr

            INNER JOIN mod_nomina.dat_cargosocupados dco  on (dco.idpersona = cpr.idpersona)

            LEFT JOIN mod_nomina.conf_plantillanominalcargo cpnc on (cpnc.idcargo = dco.idcargo)
            LEFT JOIN mod_nomina.conf_plantillanominal cpn on (cpn.idplantillanominal = cpnc.idplantillanominal)

            LEFT JOIN mod_estructuracomp.dat_cargo dc on (dc.idcargo = dco.idcargo)
            LEFT JOIN mod_estructuracomp.nom_filaestruc nfe on (nfe.idfila = dc.idcargo)
            LEFT JOIN mod_estructuracomp.nom_cargo nc on (nc.idnomcargo = dc.idnomcargo)

            INNER JOIN mod_persona.dat_persona dp on (dp.idpersona = dco.idpersona)
            
            left join mod_persona.dat_docidentidad doc on (doc.idpersona = dp.idpersona and doc.principal = 1)
            
            where dco.identidad = ? and cpr.identidad = ? and dp.feliminado is null " . $sqlconcat . " ORDER BY cpn.orden ASC, nfe.nivel ASC limit {$limite} offset {$inicio};";        
        $resultado = $conn->fetchAll($sqlDatosPersona, array($identidad, $identidad));
        $arrretpersonas = DatRetencionPersona::obtenerRetencionesEntidad($identidad);
        $arrretpersonas = $this->indexarArreglo($arrretpersonas, "idpersona");
        $arrcdgoscontables = ConfigPersonaCodigoContable::obtenerConfigDadoIdEntidad($identidad);
        $arrcdgoscontables = $this->indexarArreglo($arrcdgoscontables, "idpersona");
        $conn->commit();
        foreach ($resultado as $i => $value) {
            $arrayfinal[$cont]['idconfpersonaretencion'] = $value['idconfpersonaretencion'];
            $arrayfinal[$cont]['idpersona'] = $value['idpersona'];
            $arrayfinal[$cont]['identidad'] = $value['identidad'];
            $arrayfinal[$cont]['nombre'] = $value['nombre'];
            $arrayfinal[$cont]['snombre'] = $value['snombre'];
            $arrayfinal[$cont]['papel'] = $value['papel'];
            $arrayfinal[$cont]['sapel'] = $value['sapel'];
            $arrayfinal[$cont]['numid'] = $value['numid'];
            $arrayfinal[$cont]['idcargo'] = $value['idcargo'];
            $arrayfinal[$cont]['denomcargo'] = $value['denomcargo'];
            $arrayfinal[$cont]['idplantillanominal'] = $value['idplantillanominal'];
            $arrayfinal[$cont]['iddatretencionpersona'] = $arrretpersonas[$value['idpersona']]['idretencionpersona'];
            $arrayfinal[$cont]['plantilla'] = $value['plantilla'];
            $arrayfinal[$cont]['orden'] = $value['orden'];
            $arrayfinal[$cont]['plantillanominal'] = $value['orden'].'-'.$value['plantilla'];
            $arrayfinal[$cont]['ordencargo'] = $value['ordencargo'];
            $arrayfinal[$cont]['cdgocontable'] = ($arrcdgoscontables[$value['idpersona']]['cdgocontable'])?$arrcdgoscontables[$value['idpersona']]['cdgocontable']:'';
            $cont++;
        }      
        return $arrayfinal;
    }

    public static function obtenerCantidadDatosPersonaRetencion($identidad, $texto)
    {
        $sqltexto = "select count(distinct(dp.idpersona)) as cantidad
                        from mod_persona.dat_persona dp
                        inner JOIN mod_nomina.dat_cargosocupados dco ON (dco.idpersona = dp.idpersona )
                        inner JOIN mod_nomina.conf_personaretencion cpr ON (cpr.idpersona = dco.idpersona)
                        WHERE dp.feliminado is null
                        and (dp.nombre ilike '%$texto%' or dp.snombre ilike '%$texto%' or dp.papel ilike '%$texto%' or dp.sapel ilike '%$texto%')
                        and  ( (dp.feliminado) >= now() or dp.feliminado is null)
                        and  dco.identidad = $identidad and cpr.identidad = $identidad";

        $sql = "select count(distinct(dp.idpersona)) as cantidad
                        from mod_persona.dat_persona dp
                        inner JOIN mod_nomina.dat_cargosocupados dco ON (dco.idpersona = dp.idpersona )
                        inner JOIN mod_nomina.conf_personaretencion cpr ON (cpr.idpersona = dco.idpersona)
                        WHERE dp.feliminado is null
                        and  ( (dp.feliminado) >= now() or dp.feliminado is null)
                        and  dco.identidad = $identidad and cpr.identidad = $identidad";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        if (!empty($texto)) {
            $resp = $conn->fetchOne($sqltexto);
            return $resp;
        } else {
            $resp = $conn->fetchOne($sql);
            return $resp;
        }

    }


    public static function existeRetencionPersona($idpersona, $identidad)
    {
        //Devolviendo los datos de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('count(cpr.idconfpersonaretencion) as cantidad')
            ->from('ConfPersonaRetencion cpr')
            ->where('cpr.idpersona = ? and cpr.identidad = ?', array($idpersona, $identidad))
            ->fetchOne()
            ->cantidad;
    }

