    //Funci�n para indexar un arreglo dado un �ndice
    public function indexarArreglo($array, $indice)
    {
        $arrayfinal = array();
        foreach ($array as $valor) {
            $arrayfinal[$valor[$indice]] = $valor;
        }
        return $arrayfinal;
    }
}
